  });

  describe('Valid inputs', () => {
    test('should convert grayscale 1bpp image data to RGBA', () => {
      const params = {
        kind: 'GRAYSCALE_1BPP',
        data: new Uint8Array([0xFF, 0x00, 0xAA, 0x55])
      };

      const result = convertToRGBA(params);

      expect(result).not.toBeNull();
      expect(result).toHaveProperty('data');
      expect(result.data).toBeInstanceOf(Uint8ClampedArray);
      // For 1bpp, each bit becomes a full byte in RGBA, so 4 bytes input -> 16 pixels -> 64 bytes output
      expect(result.data.length).toBe(64);
    });

    test('should convert RGB 24bpp image data to RGBA', () => {
      const params = {
        kind: 'RGB_24BPP',
        data: new Uint8Array([255, 0, 0, 0, 255, 0, 0, 0, 255]) // 3 pixels: red, green, blue
