      globalImageCache = new GlobalImageCache();
    });

    it("should return false when ref is not in cache and page count is below threshold", () => {
      const ref = { num: 1, gen: 0 };
      const pageIndex = 0;

      // Add only one page reference, below the threshold of 2
      globalImageCache._refCache.put(ref, new Set([pageIndex]));

      expect(globalImageCache.shouldCache(ref, pageIndex + 1)).toBe(false);
    });

    it("should return true when ref is not in cache and adding new page reaches threshold", () => {
      const ref = { num: 1, gen: 0 };
      const pageIndex1 = 0;
      const pageIndex2 = 1;

      // Add first page reference
      globalImageCache._refCache.put(ref, new Set([pageIndex1]));

      // Adding second page should reach threshold and return true
      expect(globalImageCache.shouldCache(ref, pageIndex2)).toBe(true);
    });

    it("should return true when ref already has more pages than threshold", () => {
      const ref = { num: 1, gen: 0 };
      const pageIndex1 = 0;
      const pageIndex2 = 1;
      const pageIndex3 = 2;

      // Add two page references initially
      globalImageCache._refCache.put(ref, new Set([pageIndex1, pageIndex2]));

      // Adding third page should still be above threshold
      expect(globalImageCache.shouldCache(ref, pageIndex3)).toBe(true);
    });

    it("should return false when image cache size exceeds MAX_BYTE_SIZE", () => {
      const ref1 = { num: 1, gen: 0 };
      const ref2 = { num: 2, gen: 0 };

      // Fill up the image cache to exceed MAX_BYTE_SIZE
      globalImageCache._imageCache.put(ref1, { data: new Array(3e7).fill(0) }); // 30MB
      globalImageCache._imageCache.put(ref2, { data: new Array(3e7).fill(0) }); // 30MB, total now 60MB > 50MB

