      const ref = { num: 1, gen: 0 };
      const pageIndex1 = 0;
      const pageIndex2 = 1;

      globalImageCache._refCache.put(ref, new Set([pageIndex1]));

      globalImageCache.shouldCache(ref, pageIndex2);

